/**
 * What to call this install when it appears in the account's device list:
 * the phone model where the browser reveals it, otherwise the browser and
 * the operating system. Never precise enough to identify a person, always
 * enough to recognise "that is my old tablet".
 */
export function describeDevice(agent: string = navigator.userAgent): string {
  const android = /Android [^;)]+;\s*([^;)]+)/.exec(agent);
  if (android?.[1] !== undefined) {
    const model = android[1].replace(/\s+Build\/.*$/, '').trim();
    // Chrome on Android hides the model behind a generic token.
    if (model !== '' && model !== 'K') return model;
    return 'Android phone';
  }
  if (agent.includes('iPad')) return 'iPad';
  if (agent.includes('iPhone')) return 'iPhone';
  const browser = agent.includes('Edg/')
    ? 'Edge'
    : agent.includes('Firefox/')
      ? 'Firefox'
      : agent.includes('Chrome/')
        ? 'Chrome'
        : agent.includes('Safari/')
          ? 'Safari'
          : 'Browser';
  const os = agent.includes('Mac OS X')
    ? 'macOS'
    : agent.includes('Windows')
      ? 'Windows'
      : agent.includes('CrOS')
        ? 'ChromeOS'
        : agent.includes('Linux')
          ? 'Linux'
          : undefined;
  return os === undefined ? browser : `${browser} on ${os}`;
}
